create or replace function public.cinetracker_profile_screen_v495(p_tz text default 'America/Sao_Paulo') returns jsonb language sql stable security invoker set search_path=public as $$ with q as (select public.cinetracker_profile_quick_stats_v1() as d),s as (select public.cinetracker_profile_summary_v489() as d),sp as (select public.cinetracker_sports_stadium_summary_v296() as d),a as (select public.cinetracker_activity_by_day_v320(15,p_tz) as d),st as (select to_jsonb(x) as d from public.cinetracker_profile_stats() x limit 1) select jsonb_build_object('stats',coalesce((select d->'stats' from q),(select d from st),'{}'::jsonb),'series_stats',coalesce((select d->'series_stats' from q),'{}'::jsonb),'remaining',coalesce((select d->'remaining' from q),'{}'::jsonb),'activity',coalesce((select d from a),'[]'::jsonb),'summary',coalesce((select d from s),'{}'::jsonb),'sports',coalesce((select d->'sports_stats' from q),'{}'::jsonb)||jsonb_build_object('watched_events',coalesce(((select d from sp)->>'watched_events')::bigint,coalesce(((select d->'sports_stats' from q)->>'watched_events')::bigint,0)),'stadium_events',coalesce(((select d from sp)->>'stadium_events')::bigint,0)),'stadium',coalesce((select d from sp),'{}'::jsonb),'source','v495-fast-contract'); $$; revoke all on function public.cinetracker_profile_screen_v495(text) from public,anon; grant execute on function public.cinetracker_profile_screen_v495(text) to authenticated; notify pgrst,'reload schema';